const fieldLabel=(value:string)=>typeof document!=='undefined'&&document.documentElement.lang==='en'?(fieldEnglish[value]??value):value
function Field({label,value,unit,onChange,type='number',blankZero=false}:{label:string;value:number|string;unit?:string;onChange:(v:any)=>void;type?:string;blankZero?:boolean}){const displayValue=value==null?'':value;return <label className="fw-field"><span>{fieldLabel(label)}</span><div><input type={type} value={displayValue} onChange={e=>onChange(type==='number'?(e.target.value===''?null as unknown as number:Number(e.target.value)):e.target.value)}/>{unit&&<small>{fieldLabel(unit)}</small>}</div></label>}
function TechnicalParameterEditor({title,rows,onChange,language,blankZero=false}:{title:string;rows:Row[];onChange:(rows:Row[])=>void;language:'fa'|'en';blankZero?:boolean}){
 const t=(fa:string,english:string)=>language==='en'?english:fa
 const update=(id:string,key:'name'|'valueText'|'unit'|'source',value:string)=>onChange(rows.map(row=>row.id===id?{...row,[key]:value}:row))
 return <div className="fw-card"><h3>{title}</h3>
  <p className="fw-hint">{t('مقدار هر پارامتر را به‌صورت عددی یا توصیفی وارد کنید؛ برای پارامترهای کمی، واحد و منبع داده را نیز مشخص کنید.','Enter each parameter as a numeric or descriptive value; provide a unit and source for quantitative parameters.')}</p>
  {rows.map(row=><div className="fw-grid" key={row.id}>
   <label className="fw-field"><span>{fieldLabel('عنوان پارامتر')}</span><input value={row.name} onChange={event=>update(row.id,'name',event.target.value)}/></label>
   <label className="fw-field"><span>{fieldLabel('مقدار / مشخصه')}</span><input type="text" value={row.valueText??(row.quantity!=null&&row.quantity!==0?String(row.quantity):'')} onChange={event=>update(row.id,'valueText',event.target.value)}/></label>
   <label className="fw-field"><span>{fieldLabel('واحد')}</span><input value={row.unit} onChange={event=>update(row.id,'unit',event.target.value)}/></label>
   <label className="fw-field"><span>{fieldLabel('منبع داده')}</span><input value={row.source} onChange={event=>update(row.id,'source',event.target.value)}/></label>
   <button className="secondary-button" onClick={()=>onChange(rows.filter(item=>item.id!==row.id))}>{t('حذف پارامتر','Remove parameter')}</button>
  </div>)}
  <button className="secondary-button" onClick={()=>onChange([...rows,makeRow('پارامتر جدید','',blankZero?null as unknown as number:0,blankZero?null as unknown as number:0,'فرض کاربر')])}>{t('افزودن پارامتر فنی','Add Technical Parameter')}</button>
 </div>
}
function RowEditor({title,rows,onChange,defaultUnit,blankZero=false,showFlowType=false}:{title:string;rows:Row[];onChange:(rows:Row[])=>void;defaultUnit:string;blankZero?:boolean;showFlowType?:boolean}){
 const update=(id:string,key:keyof Row,value:string|number|null)=>onChange(rows.map(r=>r.id===id?{...r,[key]:value as number}:r))
 const move=(index:number,direction:number)=>{const next=[...rows],target=index+direction;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];onChange(next)}
 return <div className="fw-card"><div className="fw-card-head"><h3>{fieldLabel(title)}</h3><button className="secondary-button" onClick={()=>onChange([...rows,makeRow('قلم جدید',defaultUnit,blankZero?null as unknown as number:0,blankZero?null as unknown as number:0)])}><Plus size={15}/> {fieldLabel('افزودن ردیف')}</button></div>
  {rows.map(r=><div className="fw-row" key={r.id} style={showFlowType?{gridTemplateColumns:'minmax(130px,2fr) repeat(4,minmax(70px,1fr)) 112px auto'}:undefined}><input aria-label={fieldLabel("عنوان قلم")} value={fieldLabel(r.name)} onChange={e=>update(r.id,'name',e.target.value)}/><input aria-label={fieldLabel("مقدار")} type="number" value={r.quantity==null?'':r.quantity} onChange={e=>update(r.id,'quantity',e.target.value===''?null:Number(e.target.value))}/><input aria-label={fieldLabel("واحد")} value={fieldLabel(r.unit)} onChange={e=>update(r.id,'unit',e.target.value)}/><input aria-label={fieldLabel("قیمت واحد")} type="number" value={r.unitPrice==null?'':r.unitPrice} onChange={e=>update(r.id,'unitPrice',e.target.value===''?null:Number(e.target.value))}/><input aria-label={fieldLabel("منبع داده")} value={fieldLabel(r.source)} onChange={e=>update(r.id,'source',e.target.value)}/>{showFlowType&&<select aria-label={fieldLabel('جهت جریان')} value={r.flowType??(isOutputMaterial(r.name)?'output':'input')} onChange={e=>update(r.id,'flowType',e.target.value)}><option value="input">{fieldLabel('ورودی / مصرف')}</option><option value="output">{fieldLabel('خروجی / محصول')}</option></select>}<span className="fw-row-actions"><button className="icon-button" aria-label={fieldLabel("انتقال به بالا")} disabled={rows.indexOf(r)===0} onClick={()=>move(rows.indexOf(r),-1)}><ArrowUp size={13}/></button><button className="icon-button" aria-label={fieldLabel("انتقال به پایین")} disabled={rows.indexOf(r)===rows.length-1} onClick={()=>move(rows.indexOf(r),1)}><ArrowDown size={13}/></button><button className="icon-button" aria-label={fieldLabel("حذف ردیف")} onClick={()=>onChange(rows.filter(x=>x.id!==r.id))}><Trash2 size={15}/></button></span></div>)}
  <small className="fw-hint">{fieldLabel('عنوان · مقدار · واحد · قیمت واحد · منبع داده')}</small>
 </div>
}
